"use client";
import "./styles/skeuo-tabs.css";

import { useId } from "react";
import type { ReactNode } from "react";
export type TabItem = { value: string; label: string; content: ReactNode; disabled?: boolean };
export function SkeuoTabs({ items, value, onValueChange, label = "Tabs", appearance = "segmented", colorMode = "same" }: { items: TabItem[]; value: string; onValueChange: (value: string) => void; label?: string; appearance?: "segmented" | "keys"; colorMode?: "same" | "alternating" }) {
  const id = useId();
  const active = items.find(item => item.value === value);
  return <div data-sk-root="" className={`sk-tabs ${appearance === "keys" ? "sk-key-tabs" : ""}`} data-color-mode={colorMode}><div className="sk-segmented" role="tablist" aria-label={label}>{items.map((item, index) => <button type="button" id={`${id}-tab-${index}`} key={item.value} role="tab" aria-selected={value === item.value} aria-controls={`${id}-panel-${index}`} tabIndex={value === item.value ? 0 : -1} disabled={item.disabled} onClick={() => onValueChange(item.value)} onKeyDown={e => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) return;
    e.preventDefault();
    const available = items.map((tab, i) => ({ ...tab, index: i })).filter(tab => !tab.disabled);
    if (!available.length) return;
    const current = available.findIndex(tab => tab.value === value);
    const next = e.key === "Home" ? 0 : e.key === "End" ? available.length - 1 : (current + (e.key === "ArrowRight" ? 1 : available.length - 1)) % available.length;
    onValueChange(available[next].value);
    document.getElementById(`${id}-tab-${available[next].index}`)?.focus();
  }}>{item.label}</button>)}</div>{active && <div role="tabpanel" tabIndex={0} id={`${id}-panel-${items.indexOf(active)}`} aria-labelledby={`${id}-tab-${items.indexOf(active)}`} className="sk-tab-panel">{active.content}</div>}</div>;
}

@import "./skeuo-base.css";
.sk-segmented{ display: flex; background: var(--sk-well); border: 1px solid var(--sk-edge); border-radius: 8px; padding: 4px; box-shadow: inset 0 2px 3px var(--sk-shadow),0 1px 0 var(--sk-highlight); }
.sk-segmented button{ flex: 1; padding: 9px 12px; border: 1px solid transparent; border-radius: 5px; background: transparent; font-size: 10px; color: var(--sk-muted); }
.sk-segmented button[aria-selected="true"]{ color: var(--sk-ink); background: linear-gradient(150deg,var(--sk-surface-raised),var(--sk-surface)); border-color: var(--sk-edge); box-shadow: inset 0 1px 0 var(--sk-highlight),0 2px 2px var(--sk-shadow); }
@media(max-width:600px){.sk-segmented button{ font-size: 11px; padding: 11px; }}
.sk-tabs{ width: 100%; }
.sk-tab-panel{ padding-top: 22px; font-size: 13px; color: var(--sk-muted); line-height: 1.8; }
.sk-tabs .sk-segmented button{ font-size: 12px; }
.sk-segmented button:disabled{ opacity: .4; cursor: not-allowed; }

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root] :focus-visible) {outline:2px solid var(--sk-accent);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Namespaced defaults. Host applications can override any --sk-* token. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper:#faf9f5;--sk-album-ink:#45423b;--sk-album-edge:#c4c2ba;--sk-album-base:#d6d4ca;
  --sk-bg: #fff; --sk-ink: #202020; --sk-muted: #777774; --sk-line: #e7e7e4;
  --sk-surface: #f5f5f2; --sk-surface-raised: #fafaf8; --sk-well: #e9e9e5;
  --sk-edge: #d1d1cb; --sk-highlight: #fff; --sk-base: #d9d9d3; --sk-shadow: #00000017;
  --sk-accent: #365e50; --sk-accent-bright: #487b68; --sk-accent-base: #213c32; --sk-accent-edge: #294b3e; --sk-accent-ink: #fff;
  --sk-key: #f9f9f7; --sk-key-edge: #c6c7c1; --sk-key-base: #d0d1ca;
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

} }
